"""Independent anchors for the AV-02 reference before native framebuffer tests."""
import math
import unittest

from script.generate_playback_color_fixtures import bt2390, pq_decode, pq_encode, reference, yuv


class ColorReferenceTests(unittest.TestCase):
    def test_st2084_published_luminance_anchors(self):
        # ST.2084 absolute luminance anchors, not values generated by this test.
        for signal, nits in [(0.5080784215, 100), (0.7518270962, 1000), (1, 10000)]:
            self.assertAlmostEqual(pq_decode(signal), nits, delta=0.0001)
            self.assertAlmostEqual(pq_encode(nits), signal, delta=1e-9)

    def test_709_code_values_and_endpoints(self):
        self.assertEqual(yuv((0,0,0), "bt709", True), [64,512,512])
        self.assertEqual(yuv((1,1,1), "bt709", True), [940,512,512])
        self.assertEqual(yuv((1,1,1), "bt709", False), [1023,512,512])
        self.assertEqual(yuv((1,0,0), "bt709", True), [250,409,960])
        self.assertEqual(reference([64,512,512], "bt709", True, "bt709"), [0,0,0])
        for v in reference([940,512,512], "bt709", True, "bt709"):
            self.assertAlmostEqual(v, 1)

    def test_eetf_black_peak_and_monotonic_grey(self):
        for source_peak in [1000,10000]:
            self.assertAlmostEqual(bt2390(0, source_peak), 0, delta=1e-12)
            self.assertAlmostEqual(bt2390(source_peak, source_peak), 203, delta=1e-8)
            mapped = [bt2390(source_peak*i/100,source_peak) for i in range(101)]
            self.assertTrue(all(math.isfinite(x) for x in mapped))
            self.assertTrue(all(a <= b for a,b in zip(mapped,mapped[1:])))


if __name__ == "__main__":
    unittest.main()
